head.script:
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. Property 또는 Souce 탭에서 upload 컴포넌트(upload1) 의 subDir 을 확인한다.
    //1. In the Property or Source tab, check the subDir of the upload component (upload1).
    //Verify 1. subDir="subDirTEST"
    //Test step 2. 브라우저에서 getSubDir 버튼을 클릭한다.
    //2. Click the getSubDir button in your browser.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. subDirTEST 값이 팝업창으로 생성된다. 
    //2. The subDirTEST value is popped up.
    WebSquare.wUnit.addCommand("assert", "log", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 22-Feb-2018
    window.log = false;
    window.console.log = function(l) {
        log = true;
    }
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
